-- ESSÊNCIA 2ª edição | reversão de programação com autorização específica.
begin;
set local lock_timeout = '5s';

do $schedule$
declare
  actor_id uuid;
  actors integer;
  target public.experiences%rowtype;
  session_before public.sessions%rowtype;
  event_after public.experiences%rowtype;
  session_after public.sessions%rowtype;
  booked_before text;
  target_editorial constant jsonb := $json${"version":1,"hero":{"eyebrow":"Especial de Confraternização de Fim de Ano!","title":"ESSÊNCIA — Corpo, Mente e Natureza","subtitle":"Que tal celebrar a vida, compartilhar boas energias e receber os novos ciclos?","image":{"src":"/images/eventos/essencia-lua-cheia/hero-lua-desktop.webp","alt":"Lua cheia nascendo no céu rosado do entardecer sobre o Lago Paranoá, com remadores de colete preparando a canoa havaiana","credit":"Remada da Lua Cheia · Alma Azul Academy"},"primaryCta":{"label":"Garantir minha vaga","href":"#reserva"},"secondaryCta":{"label":"Ver a programação","href":"#programacao"},"details":["23 de novembro de 2026","16h30 às 20h","Cápsula Bar · Brasília"]},"quickFacts":[{"label":"Data","value":"23/11/2026"},{"label":"Horário","value":"16h30 às 20h"},{"label":"Local","value":"Cápsula Bar"},{"label":"Ingresso","value":"R$ 160 por pessoa"}],"about":{"eyebrow":"Corpo, mente e natureza","title":"Lua Cheia, Movimento e Autocuidado","paragraphs":["Um encontro especial de bem-estar, natureza, movimento, autocuidado, educação ambiental e conexão!"],"image":{"src":"/images/eventos/essencia-lua-cheia/apresentacao-capsula-entardecer.webp","alt":"Varal de luzes acesas no gramado do Cápsula Bar, com palmeiras e o pôr do sol sobre o Lago Paranoá"}},"reservations":{"eyebrow":"Ingresso único","title":"Garanta a sua vaga","description":"Remada, Superioga, lanche saudável, massagem ou reflexologia e educação ambiental em um único ingresso.","image":{"src":"/images/eventos/essencia-lua-cheia/reserva-capsula-noite.webp","alt":"Cápsula Bar iluminado à noite, visto do Lago Paranoá, com as luzes refletidas na água e canoas no píer"}},"seo":{"title":"ESSÊNCIA — Corpo, Mente e Natureza","description":"Especial de Confraternização de Fim de Ano no Cápsula Bar, em Brasília: remada no Lago Paranoá, Superioga, lanche saudável, massagem ou reflexologia e educação ambiental sobre o Cerrado. 23 de novembro de 2026, das 16h30 às 20h."},"event":{"theme":"dusk","badge":"Especial de Confraternização de Fim de Ano!","subtitle":"Celebração da Lua Cheia","tagline":"Que tal celebrar a vida, compartilhar boas energias e receber os novos ciclos?","highlights":["Remada no Lago Paranoá","Superioga","Lanche saudável","Bem-estar e Cerrado"],"heroImageMobile":{"src":"/images/eventos/essencia-lua-cheia/hero-lua-mobile.webp","alt":"Lua cheia nascendo no céu rosado do entardecer sobre o Lago Paranoá, com remadores de colete preparando a canoa havaiana","credit":"Remada da Lua Cheia · Alma Azul Academy"},"cardImage":{"src":"/images/eventos/essencia-lua-cheia/hero-lua-desktop.webp","alt":"Lua cheia nascendo no céu rosado do entardecer sobre o Lago Paranoá, com remadores de colete preparando a canoa havaiana"},"intro":{"eyebrow":"Corpo, mente e natureza","title":"Lua Cheia, Movimento e Autocuidado","paragraphs":["Um encontro especial de bem-estar, natureza, movimento, autocuidado, educação ambiental e conexão!","Nesta edição especial do ESSÊNCIA, vamos celebrar nossas amizades, conquistas e experiências vividas ao longo do ano, compartilhando bons momentos e agradecendo por tudo que vivemos.","Uma jornada pelas águas do Lago Paranoá, pelo movimento do corpo e pelos momentos de cuidado e conexão com a natureza."],"image":{"src":"/images/eventos/essencia-lua-cheia/apresentacao-capsula-entardecer.webp","alt":"Varal de luzes acesas no gramado do Cápsula Bar, com palmeiras e o pôr do sol sobre o Lago Paranoá"}},"program":{"eyebrow":"Programação","title":"Do fim da tarde ao despertar da Lua.","imageShape":"portrait","items":[{"time":"16:30","title":"Recepção e boas-vindas","description":"Um momento de acolhimento para iniciar nossa experiência em um ambiente de conexão e boas energias.","hosts":[],"image":{"src":"/images/eventos/essencia-lua-cheia/recepcao-deck-lago.webp","alt":"Deck do Cápsula Bar de frente para o Lago Paranoá em uma tarde de céu claro"}},{"time":"17:00","title":"Remada Alma Azul","description":"Um convite para contemplar o pôr do sol e presenciar o despertar da Lua Cheia de dentro da água. Uma remada leve em canoas havaianas, acompanhada pela equipe Alma Azul Academy. Não é necessário ter experiência prévia na modalidade.","hosts":["Alma Azul Academy"],"note":"Colete salva-vidas obrigatório, inclusive para crianças.","image":{"src":"/images/eventos/essencia-lua-cheia/remada-entardecer.webp","alt":"Canoa havaiana com remadores em silhueta sobre o Lago Paranoá, sob nuvens escuras e o céu alaranjado do pôr do sol","credit":"Remada Sunset · Alma Azul Academy"}},{"time":"17:45","title":"Superioga","description":"Movimento, energia e conexão com o corpo em uma prática especial de bem-estar.","hosts":["Rapha Dantas"],"note":"Traga seu próprio tapete.","image":{"src":"/images/eventos/essencia-lua-cheia/superioga-1a-edicao.webp","alt":"Participantes em prática de Superioga sobre tapetes no deck do Cápsula Bar","credit":"Registro da 1ª edição do ESSÊNCIA · 07/11/2026"}},{"time":"18:45","title":"Lanche saudável","description":"Momento de alimentação saudável e convivência, com o lanche da Nutre - DF.","hosts":["Nutre - DF"],"note":"Incluído no ingresso, sem cobrança adicional.","image":{"src":"/images/eventos/essencia-lua-cheia/lanche-1a-edicao.webp","alt":"Duas mesas amarelas com alimentos, bebidas e produtos à frente dos participantes em prática de yoga no Cápsula Bar","credit":"Registro da 1ª edição do ESSÊNCIA · 07/11/2026"}},{"time":"19:00","timeLabel":"19h às 20h","title":"Momento de Bem-Estar e Conexão com a Natureza","description":"Duas experiências acontecem ao mesmo tempo: massagem ou reflexologia com o Cure-se Bem e Educação Ambiental com Fernanda Garcia. Aproveite um momento enriquecedor de educação ambiental enquanto aguarda o seu atendimento.","hosts":["Cure-se Bem","Fernanda Garcia"],"parallel":[{"title":"Massagem e Reflexologia","description":"Escolha no local entre massagem relaxante ou reflexologia podal, conforme a disponibilidade dos terapeutas, com a utilização de óleos essenciais.","hosts":["Cure-se Bem"],"image":{"src":"/images/eventos/essencia-lua-cheia/bem-estar-1a-edicao.webp","alt":"Participante sentada sobre o tapete aplicando óleo essencial nas mãos, durante a aromaterapia","credit":"Registro da 1ª edição do ESSÊNCIA · 07/11/2026"}},{"title":"Educação Ambiental: Fauna e Flora do Cerrado","description":"Uma vivência educativa para crianças e adultos, com experiências de conexão com a natureza e descobertas sobre a riqueza da biodiversidade do Cerrado, seus animais, suas plantas e a importância da preservação ambiental.","hosts":["Fernanda Garcia"],"image":{"src":"/images/eventos/essencia-lua-cheia/educacao-ambiental-cerrado.webp","alt":"Mata de galeria do Cerrado acompanhando um córrego, vista do alto, com a paisagem do Distrito Federal ao fundo","credit":"Córrego do Torto · Cerrado do Distrito Federal"}}]}]},"included":{"eyebrow":"Ingresso único","title":"Tudo o que está incluso.","description":"Um único ingresso para viver a experiência completa, do fim da tarde ao despertar da Lua.","items":["Recepção e boas-vindas","Remada em canoa havaiana, com colete salva-vidas","Superioga com Rapha Dantas","Lanche saudável da Nutre - DF","Massagem relaxante ou reflexologia podal com o Cure-se Bem, conforme a disponibilidade dos terapeutas","Educação Ambiental: fauna e flora do Cerrado, com Fernanda Garcia"]},"partners":{"eyebrow":"Quem faz acontecer","title":"Uma celebração feita a muitas mãos.","items":[{"name":"Alma Azul Academy","role":"Realização · Remada em canoa havaiana","logo":{"src":"/images/branding/alma-azul-logo-dark.png","alt":"Logo Alma Azul Academy"}},{"name":"Cure-se Bem","role":"Realização · Massagem e reflexologia","logo":{"src":"/images/eventos/essencia/logo-cure-se-bem.png","alt":"Logo Cure-se Bem"}},{"name":"Cápsula Bar","role":"Realização · Local do evento","logo":{"src":"/images/bases/concha-acustica/capsula-bar-logo.webp","alt":"Logo Cápsula Bar"}},{"name":"Rapha Dantas","role":"Superioga","logo":{"src":"/images/eventos/essencia/logo-superioga-rapha-dantas.jpg","alt":"Logo Superioga — Rapha Dantas"}},{"name":"Nutre - DF","role":"Lanche saudável","logo":{"src":"/images/eventos/essencia/logo-nutre.png","alt":"Logo Nutre - DF"}},{"name":"Fernanda Garcia","role":"Educação Ambiental · fauna e flora do Cerrado"}]},"info":{"eyebrow":"Antes de ir","title":"Informações importantes","items":[{"id":"chegada","title":"Horário e chegada","body":"A chegada e a recepção começam às 16h30, no Cápsula Bar, às margens do Lago Paranoá.\n\nA tolerância máxima de chegada é até 16h50: às 17h00 começa a remada.\n\nA programação vai até as 20h00."},{"id":"o-que-levar","title":"O que levar","body":"Roupas confortáveis que possam molhar, muda de roupa, toalha, tapete próprio para a Superioga, garrafa de água, repelente e um agasalho leve para a noite."},{"id":"criancas","title":"Participação de crianças","body":"Crianças são bem-vindas e participam somente acompanhadas por um responsável.\n\nCada criança paga o mesmo ingresso (R$ 160) e conta na capacidade total de 24 participantes. Durante a remada, o uso de colete salva-vidas adequado é obrigatório.","email":true},{"id":"seguranca","title":"Segurança na remada","body":"A remada é realizada em canoas havaianas, com acompanhamento da equipe Alma Azul Academy e uso obrigatório de colete salva-vidas para todos os participantes, inclusive crianças, com colete adequado.\n\nA realização da atividade na água depende de condições seguras de navegação."},{"id":"alimentacao","title":"Lanche saudável","body":"O ingresso inclui o lanche saudável da Nutre - DF, servido às 18h45, sem cobrança adicional."},{"id":"clima","title":"Condições climáticas","body":"Se as condições climáticas impedirem a realização segura das atividades, o evento inteiro será reagendado — remada, Superioga, lanche saudável, massagem e reflexologia e Educação Ambiental — e a nova data será comunicada aos participantes.\n\nO evento não é realizado em versão parcial nessas condições."},{"id":"cancelamento","title":"Política de cancelamento","body":"Você pode solicitar o cancelamento até 21 de novembro de 2026, às 12h00 (horário de Brasília), escolhendo entre crédito para outra experiência da Alma Azul Academy ou reembolso, conforme a política aplicável e os direitos do consumidor.\n\nAs solicitações são atendidas pela nossa equipe, pelos canais oficiais de atendimento."}]},"arrival":{"startTime":"16:30","toleranceUntil":"16:50"},"cancellation":{"deadline":"2026-11-21T12:00:00-03:00","timeZone":"America/Sao_Paulo","summary":"crédito para outra experiência da Alma Azul Academy ou reembolso, pelo atendimento da nossa equipe"},"reservation":{"eyebrow":"Celebre os novos ciclos com a gente","title":"Garanta a sua vaga","ctaLabel":"Garantir minha vaga","maxPerOrder":6,"notice":"Traga seu próprio tapete para a Superioga. Crianças participam somente acompanhadas por um responsável.","comingSoon":false,"image":{"src":"/images/eventos/essencia-lua-cheia/reserva-capsula-noite.webp","alt":"Cápsula Bar iluminado à noite, visto do Lago Paranoá, com as luzes refletidas na água e canoas no píer"}}}}$json$::jsonb;
begin
  select count(*), min(au.user_id::text)::uuid into actors, actor_id from public.admin_users au join auth.users u on u.id = au.user_id
  where lower(u.email) = 'almaazulacademy@gmail.com' and au.is_active and au.role = 'ADMIN';
  if actors <> 1 or not (exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'experiences' and policyname = 'events hidden until published')
     and exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'sessions' and policyname = 'event sessions hidden until published')
     and exists (select 1 from pg_trigger where tgrelid = 'public.reservations'::regclass and tgname = 'reservations_event_publication_guard')
     and exists (select 1 from pg_trigger where tgrelid = 'public.waitlist_entries'::regclass and tgname = 'waitlist_entries_event_publication_guard')
     and exists (select 1 from pg_proc where proname = 'event_publication_allows' and pronamespace = 'public'::regnamespace)) then
    raise exception 'EVENTO_PROGRAMACAO_SEGURANCA: administrador ou proteções divergentes';
  end if;

  -- A pré-reserva também trava a sessão antes de consultar a experiência.
  select * into session_before from public.sessions s where s.id = '70c6a4a4-1fa9-4941-850d-b62b26135c31' and s.experience_id = '7755ad49-ca13-40ec-aaf0-234f62db2555' for update;
  if not found or (session_before.status = 'OPEN' and session_before.starts_at = '2026-11-23T20:15:00.000Z'::timestamptz
    and session_before.duration_minutes = 195 and session_before.price_cents = 16000 and session_before.capacity = 24) is not true then
    raise exception 'EVENTO_PROGRAMACAO_SESSAO: estado, horário ou parâmetros de origem divergentes';
  end if;
  select e.* into target from public.experiences e where e.id = '7755ad49-ca13-40ec-aaf0-234f62db2555' and e.slug = 'essencia-lua-cheia' and e.kind = 'EVENT' for update;
  if not found or (target.status = 'PUBLISHED' and target.title = 'ESSÊNCIA — Corpo, Mente e Natureza'
    and target.editorial_content = $json${"version":1,"hero":{"eyebrow":"Especial de Confraternização de Fim de Ano!","title":"ESSÊNCIA — Corpo, Mente e Natureza","subtitle":"Que tal celebrar a vida, compartilhar boas energias e receber os novos ciclos?","image":{"src":"/images/eventos/essencia-lua-cheia/hero-lua-desktop.webp","alt":"Lua cheia nascendo no céu rosado do entardecer sobre o Lago Paranoá, com remadores de colete preparando a canoa havaiana","credit":"Remada da Lua Cheia · Alma Azul Academy"},"primaryCta":{"label":"Garantir minha vaga","href":"#reserva"},"secondaryCta":{"label":"Ver a programação","href":"#programacao"},"details":["23 de novembro de 2026","17h15 às 20h30","Cápsula Bar · Brasília"]},"quickFacts":[{"label":"Data","value":"23/11/2026"},{"label":"Horário","value":"17h15 às 20h30"},{"label":"Local","value":"Cápsula Bar"},{"label":"Ingresso","value":"R$ 160 por pessoa"}],"about":{"eyebrow":"Corpo, mente e natureza","title":"Lua Cheia, Movimento e Autocuidado","paragraphs":["Um encontro especial de bem-estar, natureza, movimento, autocuidado, educação ambiental e conexão!"],"image":{"src":"/images/eventos/essencia-lua-cheia/apresentacao-capsula-entardecer.webp","alt":"Varal de luzes acesas no gramado do Cápsula Bar, com palmeiras e o pôr do sol sobre o Lago Paranoá"}},"reservations":{"eyebrow":"Ingresso único","title":"Garanta a sua vaga","description":"Remada, Superioga, lanche saudável, massagem ou reflexologia e educação ambiental em um único ingresso.","image":{"src":"/images/eventos/essencia-lua-cheia/reserva-capsula-noite.webp","alt":"Cápsula Bar iluminado à noite, visto do Lago Paranoá, com as luzes refletidas na água e canoas no píer"}},"seo":{"title":"ESSÊNCIA — Corpo, Mente e Natureza","description":"Especial de Confraternização de Fim de Ano no Cápsula Bar, em Brasília: remada no Lago Paranoá, Superioga, lanche saudável, massagem ou reflexologia e educação ambiental sobre o Cerrado. 23 de novembro de 2026, das 17h15 às 20h30."},"event":{"theme":"dusk","badge":"Especial de Confraternização de Fim de Ano!","subtitle":"Celebração da Lua Cheia","tagline":"Que tal celebrar a vida, compartilhar boas energias e receber os novos ciclos?","highlights":["Remada no Lago Paranoá","Superioga","Lanche saudável","Bem-estar e Cerrado"],"heroImageMobile":{"src":"/images/eventos/essencia-lua-cheia/hero-lua-mobile.webp","alt":"Lua cheia nascendo no céu rosado do entardecer sobre o Lago Paranoá, com remadores de colete preparando a canoa havaiana","credit":"Remada da Lua Cheia · Alma Azul Academy"},"cardImage":{"src":"/images/eventos/essencia-lua-cheia/hero-lua-desktop.webp","alt":"Lua cheia nascendo no céu rosado do entardecer sobre o Lago Paranoá, com remadores de colete preparando a canoa havaiana"},"intro":{"eyebrow":"Corpo, mente e natureza","title":"Lua Cheia, Movimento e Autocuidado","paragraphs":["Um encontro especial de bem-estar, natureza, movimento, autocuidado, educação ambiental e conexão!","Nesta edição especial do ESSÊNCIA, vamos celebrar nossas amizades, conquistas e experiências vividas ao longo do ano, compartilhando bons momentos e agradecendo por tudo que vivemos.","Uma jornada pelas águas do Lago Paranoá, pelo movimento do corpo e pelos momentos de cuidado e conexão com a natureza."],"image":{"src":"/images/eventos/essencia-lua-cheia/apresentacao-capsula-entardecer.webp","alt":"Varal de luzes acesas no gramado do Cápsula Bar, com palmeiras e o pôr do sol sobre o Lago Paranoá"}},"program":{"eyebrow":"Programação","title":"Do fim da tarde ao despertar da Lua.","imageShape":"portrait","items":[{"time":"17:15","title":"Recepção e acolhimento","description":"Chegada e preparação para a experiência.","hosts":[],"image":{"src":"/images/eventos/essencia-lua-cheia/recepcao-deck-lago.webp","alt":"Deck do Cápsula Bar de frente para o Lago Paranoá em uma tarde de céu claro"}},{"time":"17:30","title":"Remada Alma Azul","description":"Uma remada ao entardecer no Lago Paranoá e um momento para contemplar o despertar da Lua Cheia, conforme as condições naturais. Não é necessário ter experiência prévia.","hosts":["Alma Azul Academy"],"note":"Colete salva-vidas obrigatório, inclusive para crianças.","image":{"src":"/images/eventos/essencia-lua-cheia/remada-entardecer.webp","alt":"Canoa havaiana com remadores em silhueta sobre o Lago Paranoá, sob nuvens escuras e o céu alaranjado do pôr do sol","credit":"Remada Sunset · Alma Azul Academy"}},{"time":"18:30","title":"Superioga e dinâmica educativa","description":"As duas atividades acontecem ao mesmo tempo. A dinâmica é opcional e foi pensada principalmente para crianças e adolescentes, que devem permanecer sob supervisão adequada de seus responsáveis.","hosts":[],"parallel":[{"title":"Superioga","description":"Corpo, respiração e presença. Traga seu próprio tapete.","hosts":["Rapha Dantas"],"image":{"src":"/images/eventos/essencia-lua-cheia/superioga-1a-edicao.webp","alt":"Participantes em prática de Superioga sobre tapetes no deck do Cápsula Bar","credit":"Registro da 1ª edição do ESSÊNCIA · 07/11/2026"}},{"title":"Dinâmica educativa sobre a fauna e a flora do Cerrado","description":"Enquanto os adultos praticam Superioga, crianças e adolescentes podem explorar e aprender sobre o Cerrado de forma lúdica, com supervisão adequada de seus responsáveis.","hosts":["Instituto Equilibraí","Fernanda Garcia"],"image":{"src":"/images/eventos/essencia-lua-cheia/educacao-ambiental-cerrado.webp","alt":"Mata de galeria do Cerrado acompanhando um córrego, vista do alto, com a paisagem do Distrito Federal ao fundo","credit":"Córrego do Torto · Cerrado do Distrito Federal"}}]},{"time":"19:30","title":"Lanche saudável","description":"Momento de alimentação saudável e convivência, com o lanche da Nutre - DF.","hosts":["Nutre - DF"],"note":"Incluído no ingresso, sem cobrança adicional.","image":{"src":"/images/eventos/essencia-lua-cheia/lanche-1a-edicao.webp","alt":"Duas mesas amarelas com alimentos, bebidas e produtos à frente dos participantes em prática de yoga no Cápsula Bar","credit":"Registro da 1ª edição do ESSÊNCIA · 07/11/2026"}},{"time":"19:30","timeLabel":"19h30 às 20h30","title":"Autocuidado com Cure-se Bem","description":"O lanche e os atendimentos começam às 19h30. Escolha entre massagem terapêutica ou reflexologia podal, conforme a disponibilidade dos profissionais.","hosts":["Cure-se Bem"],"image":{"src":"/images/eventos/essencia-lua-cheia/bem-estar-1a-edicao.webp","alt":"Participante sentada sobre o tapete aplicando óleo essencial nas mãos, durante a aromaterapia","credit":"Registro da 1ª edição do ESSÊNCIA · 07/11/2026"}}]},"included":{"eyebrow":"Ingresso único","title":"Tudo o que está incluso.","description":"Um único ingresso para viver a experiência completa, do fim da tarde ao despertar da Lua.","items":["Recepção e acolhimento","Remada em canoa havaiana, com colete salva-vidas","Superioga com Rapha Dantas","Lanche saudável da Nutre - DF","Massagem terapêutica ou reflexologia podal com o Cure-se Bem, conforme a disponibilidade dos profissionais","Dinâmica educativa opcional sobre o Cerrado, com o Instituto Equilibraí e Fernanda Garcia"]},"partners":{"eyebrow":"Quem faz acontecer","title":"Uma celebração feita a muitas mãos.","items":[{"name":"Alma Azul Academy","role":"Realização · Remada em canoa havaiana","logo":{"src":"/images/branding/alma-azul-logo-dark.png","alt":"Logo Alma Azul Academy"}},{"name":"Cure-se Bem","role":"Realização · Massagem e reflexologia","logo":{"src":"/images/eventos/essencia/logo-cure-se-bem.png","alt":"Logo Cure-se Bem"}},{"name":"Cápsula Bar","role":"Realização · Local do evento","logo":{"src":"/images/bases/concha-acustica/capsula-bar-logo.webp","alt":"Logo Cápsula Bar"}},{"name":"Rapha Dantas","role":"Superioga","logo":{"src":"/images/eventos/essencia/logo-superioga-rapha-dantas.jpg","alt":"Logo Superioga — Rapha Dantas"}},{"name":"Nutre - DF","role":"Lanche saudável","logo":{"src":"/images/eventos/essencia/logo-nutre.png","alt":"Logo Nutre - DF"}},{"name":"Instituto Equilibraí","role":"Dinâmica educativa · fauna e flora do Cerrado, com Fernanda Garcia"}]},"info":{"eyebrow":"Antes de ir","title":"Informações importantes","items":[{"id":"chegada","title":"Horário e chegada","body":"A chegada e a recepção começam às 17h15, no Cápsula Bar, às margens do Lago Paranoá. A tolerância de chegada vai até as 17h30, horário de início da remada. A programação termina às 20h30."},{"id":"o-que-levar","title":"O que levar","body":"Roupas confortáveis que possam molhar, muda de roupa, toalha, tapete próprio para a Superioga, garrafa de água, repelente e um agasalho leve para a noite."},{"id":"criancas","title":"Participação de crianças","body":"Crianças são bem-vindas e participam somente acompanhadas por um responsável. A dinâmica educativa é opcional e os menores continuam sob supervisão adequada de seus responsáveis.\n\nCada criança paga o mesmo ingresso (R$ 160) e conta na capacidade total de 24 participantes. Durante a remada, o uso de colete salva-vidas adequado é obrigatório.","email":true},{"id":"seguranca","title":"Segurança na remada","body":"A remada é realizada em canoas havaianas, com acompanhamento da equipe Alma Azul Academy e uso obrigatório de colete salva-vidas para todos os participantes, inclusive crianças, com colete adequado.\n\nA realização da atividade na água depende de condições seguras de navegação."},{"id":"alimentacao","title":"Lanche saudável","body":"O ingresso inclui o lanche saudável da Nutre - DF, servido às 19h30, sem cobrança adicional."},{"id":"clima","title":"Condições climáticas","body":"Se as condições climáticas impedirem a realização segura das atividades, o evento inteiro será reagendado — remada, Superioga, lanche saudável, massagem e reflexologia e Educação Ambiental — e a nova data será comunicada aos participantes.\n\nO evento não é realizado em versão parcial nessas condições."},{"id":"cancelamento","title":"Política de cancelamento","body":"Você pode solicitar o cancelamento até 21 de novembro de 2026, às 12h00 (horário de Brasília), escolhendo entre crédito para outra experiência da Alma Azul Academy ou reembolso, conforme a política aplicável e os direitos do consumidor.\n\nAs solicitações são atendidas pela nossa equipe, pelos canais oficiais de atendimento."}]},"arrival":{"startTime":"17:15","toleranceUntil":"17:30"},"cancellation":{"deadline":"2026-11-21T12:00:00-03:00","timeZone":"America/Sao_Paulo","summary":"crédito para outra experiência da Alma Azul Academy ou reembolso, pelo atendimento da nossa equipe"},"reservation":{"eyebrow":"Celebre os novos ciclos com a gente","title":"Garanta a sua vaga","ctaLabel":"Garantir minha vaga","maxPerOrder":6,"notice":"Traga seu próprio tapete para a Superioga. Crianças participam somente acompanhadas por um responsável.","comingSoon":false,"image":{"src":"/images/eventos/essencia-lua-cheia/reserva-capsula-noite.webp","alt":"Cápsula Bar iluminado à noite, visto do Lago Paranoá, com as luzes refletidas na água e canoas no píer"}}}}$json$::jsonb
    and target.duration_minutes = 195 and target.price_cents = 16000
    and target.default_capacity = 24
    and exists (select 1 from public.bases b where b.id = target.base_id and b.slug = 'concha-acustica' and b.status = 'ACTIVE')) is not true then
    raise exception 'EVENTO_PROGRAMACAO_ORIGEM: editorial, publicação ou parâmetros divergentes';
  end if;
  if session_before.starts_at <= now() or '2026-11-23T19:30:00.000Z'::timestamptz <= now()
     or exists (select 1 from public.sessions s join public.experiences e on e.id = s.experience_id
    where e.base_id = target.base_id and s.id <> '70c6a4a4-1fa9-4941-850d-b62b26135c31' and s.status not in ('CANCELLED', 'ARCHIVED')
      and s.starts_at < '2026-11-23T19:30:00.000Z'::timestamptz + make_interval(mins => 210)
      and s.starts_at + make_interval(mins => s.duration_minutes) > '2026-11-23T19:30:00.000Z'::timestamptz)
     or (select count(*) from public.get_public_event('essencia-lua-cheia')) <> 1
     or not public.experience_editorial_is_publishable(target_editorial) then
    raise exception 'EVENTO_PROGRAMACAO_AGENDA: destino inválido, sobreposição ou página indisponível';
  end if;

  select (select md5(coalesce(string_agg(concat_ws(':', r.id, r.status, r.quantity), ',' order by r.id), ''))
  from public.reservations r where r.session_id = '70c6a4a4-1fa9-4941-850d-b62b26135c31') into booked_before;
  if booked_before is distinct from (
    select a.metadata ->> 'reservations_fingerprint' from public.admin_audit_log a
    where a.entity_id = session_before.id and a.action = 'ESSENCIA_SCHEDULE_UPDATED'
      and a.metadata ->> 'direction' = 'update'
    order by a.created_at desc limit 1
  ) then
    raise exception 'EVENTO_PROGRAMACAO_REVERSAO: reservas mudaram desde a atualização';
  end if;

  -- A RPC admin_update_session expira pré-reservas vencidas. Esta operação
  -- escreve apenas os campos do horário e do editorial, com auditoria própria.
  update public.experiences set duration_minutes = 210, editorial_content = target_editorial, updated_at = now()
    where id = target.id returning * into event_after;
  update public.sessions set starts_at = '2026-11-23T19:30:00.000Z'::timestamptz, duration_minutes = 210
    where id = session_before.id returning * into session_after;

  if (to_jsonb(event_after) - array['editorial_content', 'duration_minutes', 'updated_at'])
        is distinct from (to_jsonb(target) - array['editorial_content', 'duration_minutes', 'updated_at'])
     or (to_jsonb(session_after) - array['starts_at', 'duration_minutes', 'updated_at'])
        is distinct from (to_jsonb(session_before) - array['starts_at', 'duration_minutes', 'updated_at'])
     or event_after.editorial_content is distinct from target_editorial
     or event_after.duration_minutes is distinct from 210
     or (session_after.status = 'OPEN' and session_after.starts_at = '2026-11-23T19:30:00.000Z'::timestamptz
    and session_after.duration_minutes = 210 and session_after.price_cents = 16000 and session_after.capacity = 24) is not true
     or (select count(*) from public.get_public_event('essencia-lua-cheia')) <> 1 then
    raise exception 'EVENTO_PROGRAMACAO_RESULTADO: alteração fora do escopo ou página indisponível';
  end if;

  insert into public.admin_audit_log (actor_user_id, action, entity_type, entity_id, metadata)
  values (actor_id, 'ESSENCIA_SCHEDULE_UPDATED', 'SESSION', session_before.id, jsonb_build_object(
    'direction', 'rollback', 'experience_id', target.id,
    'from_starts_at', session_before.starts_at, 'to_starts_at', session_after.starts_at,
    'from_duration_minutes', session_before.duration_minutes, 'to_duration_minutes', session_after.duration_minutes,
    'reservations_fingerprint', booked_before
  ));
  raise notice 'EVENTO_PROGRAMACAO_REVERTIDA experienceId=% sessionId=%', target.id, session_before.id;
end;
$schedule$;
commit;
